<?php $identity = msc_screen_identity(); $key = get_option( 'msc_site_identity', 'a' ); ?>
<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php wp_head(); ?></head>
<body <?php body_class(); ?> data-identity="<?php echo esc_attr( $key ); ?>"><?php wp_body_open(); ?><a class="skip-link" href="#main">Skip to content</a>
<div class="site-ribbon"><div class="container"><span><?php echo esc_html( $identity['label'] ); ?> <span class="ribbon-note">· Presentation demo</span></span><nav aria-label="Test sites"><?php msc_network_switcher(); ?></nav></div></div>
<header class="network-masthead"><div class="container masthead-top"><a class="brand" href="<?php echo esc_url( home_url( '/' ) ); ?>" aria-label="<?php echo esc_attr( $identity['name'] . ' home' ); ?>"><img src="<?php echo esc_url( get_template_directory_uri() . '/assets/network/logo-' . $key . '.svg' ); ?>" alt="<?php echo esc_attr( $identity['name'] ); ?>"></a><span class="masthead-tagline"><?php echo esc_html( $identity['tagline'] ); ?></span><button class="menu-toggle" aria-expanded="false" aria-controls="network-navigation">Menu <span aria-hidden="true">☰</span></button></div>
<div id="network-navigation" class="container network-navigation"><nav class="primary-nav" aria-label="Main navigation"><?php foreach ( $identity['nav'] as $label ) { if ( 'Reviews' === $label && ! \MSC\Reviews::enabled() ) { continue; } $url = 'Home' === $label ? home_url( '/' ) : ( 'Reviews' === $label ? get_post_type_archive_link( 'msc_review' ) : msc_news_category_url( $label ) ); echo '<a href="' . esc_url( $url ) . '">' . esc_html( $label ) . '</a>'; } ?></nav><form role="search" class="header-search" method="get" action="<?php echo esc_url( home_url( '/' ) ); ?>"><label class="screen-reader-text" for="network-search">Search this site</label><input id="network-search" type="search" name="s" placeholder="Search" value="<?php echo get_search_query(); ?>"><button type="submit" aria-label="Search">⌕</button></form></div></header>
<div class="catalog-navigation"><nav class="container" aria-label="Catalog navigation"><span>Catalog</span><?php foreach ( array( 'msc_movie' => 'Movies', 'msc_show' => 'TV Shows', 'msc_person' => 'People', 'msc_game' => 'Video Games' ) as $type => $label ) { if ( \MSC\Schema::enabled( $type ) && ( $url = get_post_type_archive_link( $type ) ) ) { echo '<a href="' . esc_url( $url ) . '">' . esc_html( $label ) . '</a>'; } } ?><?php if ( \MSC\Reviews::enabled() ) { ?><a href="<?php echo esc_url( get_post_type_archive_link( 'msc_review' ) ); ?>">Reviews</a><?php } ?><a class="calendar-nav-link" href="<?php echo esc_url( \MSC\NetworkSites::calendar_url() ); ?>">Release Calendar <span aria-hidden="true">↗</span></a></nav></div><main id="main" class="container">
